node -e "
const crypto = require('crypto');
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

const reminderId = crypto.randomUUID();
const now = Date.now() / 1000;
// Set reminder for ~1 hour from now
const reminderTime = now + 3600;

const content = 'Review updated cart: gift wrap enabled for Northline Wool Blend Throw Blanket (CI-0011), CableCraft USB-C Organizer Strap 2-Pack (CI-0012) removed.';

db.prepare(
  'INSERT INTO ts_reminders (reminder_id, content, creation_timestamp, reminder_timestamp) VALUES (?, ?, ?, ?)'
).run(reminderId, content, now, reminderTime);

// Verify
const row = db.prepare('SELECT * FROM ts_reminders WHERE reminder_id = ?').get(reminderId);
console.log('Created reminder:', JSON.stringify(row, null, 2));
db.close();
"
